//! 🎟️ Original source headers retain actual pointer and payload allocations under zero alias-copy authority.
use crate::{RetainedCloneSource,RetainedCloneGrant,RetainedCloneProgress,observe_retirement_allocations};
use crate::source_law_bank::{Bank,observed,settled,CPU};
fn exact_grant(d:crate::RetirementDemand,bank:&Bank)->RetainedCloneGrant{bank.grant(d)}

fn close_original_header_source<A:crate::retirement::RetireOwned+Sync>(mut source:RetainedCloneSource<String,A>,original:*const u8,body:usize,mut born:usize,mut released:usize,bank:&mut Bank){
    let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:source.borrow().binding_copy_bytes()+crate::RetainedOwnedProjection::<str>::constructor_demand().copy_bytes,maximum_depth:1,..Default::default()};
    for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observed(denied,CPU,&mut None,|effect|source.project_owned(0,|value|value.as_str(),effect));assert_eq!(heap,(0,0));assert!(result.result.is_err());assert_eq!(source.borrow().get().as_ptr(),original);}
    let((mut projection,receipt),heap)=bank.success_eff(grant,|effect|source.project_owned(0,|value|value.as_str(),effect),|(_,p)|*p);assert_eq!(heap,(0,0));assert_eq!(receipt,RetainedCloneProgress{copied_items:1,copied_bytes:crate::RetainedOwnedProjection::<str>::constructor_demand().copy_bytes,..Default::default()});assert_eq!(projection.borrow().unwrap().get().as_ptr(),original);
    let mut binding=None;let(progress,heap)=bank.success_eff(grant,|effect|source.borrow().project(5,|value|value.as_str()).bind(&mut binding,effect),|p|p.unwrap_or_default());assert_eq!(heap,(0,0));assert_eq!(progress.unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:source.borrow().binding_copy_bytes(),..Default::default()});
    let(refused,heap)=observed(grant,CPU,&mut None,|effect|source.borrow().project(6,|value|value.as_str()).bind(&mut binding,effect));assert_eq!(heap,(0,0));assert!(refused.result.is_err());assert_eq!(source.borrow().get().as_ptr(),original);
    for _ in 0..10000{if binding.is_none(){break;}let d=crate::RetainedCloneBinding::close_demand(&binding,body).unwrap();let grant=exact_grant(d,bank);assert_eq!(crate::RetainedCloneBinding::close_demand(&binding,grant.maximum_copy_bytes).unwrap(),d);let(step,heap)=bank.success_eff(grant,|effect|settled(crate::RetainedCloneBinding::close_one(&mut binding,effect)),|s|s.progress());let receipt=step.progress();assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;released+=heap.1;assert!(receipt.copied_items!=0);}assert!(binding.is_none());
    let((mut child,receipt),heap)=bank.success_eff(grant,|effect|projection.project(2,|value|value,effect),|(_,p)|*p);assert_eq!(heap,(0,0));assert_eq!(receipt,RetainedCloneProgress{copied_items:1,copied_bytes:crate::RetainedOwnedProjection::<str>::constructor_demand().copy_bytes,..Default::default()});assert_eq!(child.borrow().unwrap().get().as_ptr(),original);
    for alias in [&mut child,&mut projection]{for _ in 0..10000{if alias.terminal_is_empty(){break;}let(demand,heap)=observe_retirement_allocations(||alias.next_close_demand(body).unwrap());assert_eq!(heap,(0,0));let grant=exact_grant(demand,bank);assert_eq!(alias.next_close_demand(grant.maximum_copy_bytes).unwrap(),demand);let quote=alias.close_work_demand(body).unwrap();let mut actual=0;let(step,heap)=bank.success_eff(grant,|effect|{let turn=settled(alias.close_step(effect));actual=turn.work;turn},|s|s.progress());assert!(actual<=u128::from(quote));let receipt=step.progress();assert!(receipt.fits(grant));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;released+=heap.1;assert!(receipt.copied_items!=0);}assert!(alias.terminal_is_empty());assert_eq!(alias.close_work_demand(body).unwrap(),0);assert_eq!(source.borrow().get().as_ptr(),original);}
    assert_eq!(observe_retirement_allocations(||drop(child)).1,(0,0));assert_eq!(observe_retirement_allocations(||drop(projection)).1,(0,0));
    for _ in 0..10000{if source.terminal_is_empty(){break;}let(demand,heap)=observe_retirement_allocations(||source.next_close_demand(body).unwrap());assert_eq!(heap,(0,0));let grant=exact_grant(demand,bank);assert_eq!(source.next_close_demand(grant.maximum_copy_bytes).unwrap(),demand);let(step,heap)=bank.success_eff(grant,|effect|settled(source.close_step(effect)),|s|s.progress());let receipt=step.progress();assert!(receipt.fits(grant));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;released+=heap.1;assert!(receipt.copied_items!=0,"original source header close stalled at literal body");}
    assert!(source.terminal_is_empty());assert_eq!(observe_retirement_allocations(||drop(source)).1,(0,0));assert_eq!(born,released);
}

#[test]
fn original_owned_and_borrowed_source_headers_preserve_pointer_and_actual_capacity(){
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎟️header.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../../🧬️schema/🎟️header.json")).unwrap();assert_eq!(schema["const"],law);
    for body in law["cancelBodies"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;let mut bank=Bank::new();
        let((owner,authority),factory)=observe_retirement_allocations(||(law["owner"].as_str().unwrap().to_owned(),law["authority"].as_str().unwrap().to_owned()));let original=owner.as_ptr();let demand=RetainedCloneSource::<String>::owned_constructor_demand::<String>();assert_eq!(RetainedCloneSource::<String>::constructor_copy_bytes(),0);
        let(source,receipt,quoted)=bank.source_quoted(RetainedCloneSource::admission_owned(owner,authority));assert_eq!(receipt.retained_capacity_bytes,demand.capacity_bytes);assert_eq!(receipt,RetainedCloneProgress{copied_items:law["headerAdmission"]["turns"].as_u64().unwrap()as usize,copied_bytes:quoted.expect("every admission turn quotes exactly the bytes it places"),retained_capacity_bytes:demand.capacity_bytes,..Default::default()});close_original_header_source(source,original,body,factory.0+receipt.retained_capacity_bytes,factory.1+receipt.released_bytes,&mut bank);
        let((owner,authority),factory)=observe_retirement_allocations(||(law["owner"].as_str().unwrap().to_owned(),law["authority"].as_str().unwrap().to_owned()));let pointers=(owner.as_ptr(),authority.as_ptr());let demand=RetainedCloneSource::<String>::borrowed_constructor_demand::<(String,String)>();assert_eq!(RetainedCloneSource::<String>::borrowed_constructor_copy_bytes::<(String,String)>(),0);let mut admission=RetainedCloneSource::<String,(String,String)>::admission_borrowed((owner,authority),|value|&value.0);
        for axis in ["items","capacity","depth"]{bank.denied(&mut admission,axis);let original=admission.original_authority().unwrap();assert_eq!((original.0.as_ptr(),original.1.as_ptr()),pointers);}
        let(source,receipt,quoted)=bank.source_quoted(admission);assert_eq!(receipt.retained_capacity_bytes,demand.capacity_bytes);assert_eq!(receipt,RetainedCloneProgress{copied_items:law["headerAdmission"]["turns"].as_u64().unwrap()as usize,copied_bytes:quoted.expect("every admission turn quotes exactly the bytes it places"),retained_capacity_bytes:demand.capacity_bytes,..Default::default()});close_original_header_source(source,pointers.0,body,factory.0+receipt.retained_capacity_bytes,factory.1+receipt.released_bytes,&mut bank);
    }
}
